const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number.isFinite(value)?String(Number(value.toPrecision(7))):'—';
export function abilityDebugPage(object,{section='attributes',offset=0,limit=64}={}){
 if(!['attributes','abilities','effects'].includes(section)||!Number.isInteger(offset)||offset<0||!Number.isInteger(limit)||limit<1||limit>256)throw Error('능력 진단 구역·페이지를 확인하세요.');const state=object?.gameplayDebug?.ability;if(!state)return {ready:false,total:0,items:[]};const table=section==='attributes'?state.attributes:section==='abilities'?state.abilities:null,keys=table?Object.keys(table):null,total=keys?keys.length:state.effects.length,items=keys?keys.slice(offset,offset+limit).map(key=>({...structuredClone(table[key]),[section==='attributes'?'name':'asset']:key})):structuredClone(state.effects.slice(offset,offset+limit));return {ready:true,owner:object.id,time:state.time,section,total,offset,items};
}
const readoutOwners=new WeakMap(),readoutRoots=new WeakSet();
const signature=state=>JSON.stringify([Object.keys(state?.attributes||{}),Object.keys(state?.abilities||{}),(state?.effects||[]).map(e=>e.handle)]);
export function abilityReadout(state={},view={}){
 const page=(rows,section)=>{const offset=Math.floor(Math.max(0,Math.min(view[section]||0,Math.max(0,rows.length-1)))/25)*25;view[section]=offset;return rows.slice(offset,offset+25);},navigation=(total,section)=>total>25?'<div class="ability-readout-pages"><button data-ability-page="'+section+'" data-ability-page-delta="-25" '+(view[section]===0?'disabled':'')+'>이전</button><output>'+(view[section]+1)+'–'+Math.min(total,view[section]+25)+' / '+total+'</output><button data-ability-page="'+section+'" data-ability-page-delta="25" '+(view[section]+25>=total?'disabled':'')+'>다음</button></div>':'';
 const cell=(key,value)=>'<td data-ability-field="'+esc(key)+'" title="'+esc(value)+'">'+esc(typeof value==='number'?(/\|(cooldown|remaining)$/.test(key)&&value>=0?value.toFixed(2):number(value)):value)+'</td>',attributes=page(Object.entries(state.attributes||{}),'attributes').map(([name,row])=>'<tr><th scope=row>'+esc(name)+'</th>'+['base','current','min','max'].map(key=>cell('attribute|'+name+'|'+key,row[key])).join('')+'</tr>').join(''),abilities=page(Object.entries(state.abilities||{}),'abilities').map(([asset,row])=>'<tr><th scope=row title="'+esc(asset)+'">'+esc(asset.split('/').at(-1).replace('.hbability.json',''))+'</th>'+cell('ability|'+asset+'|active',row.active?'활성':'대기')+cell('ability|'+asset+'|cooldown',row.cooldown)+'</tr>').join(''),effects=page(state.effects||[],'effects').map(row=>'<tr><th scope=row title="'+esc(row.asset)+'">'+esc(row.asset.split('/').at(-1).replace('.hbeffect.json',''))+' <span data-ability-field="effect|'+esc(row.handle)+'|inhibited" title="효과 상태">'+(row.inhibited?'억제':'활성')+'</span> <button type="button" data-effect-details="'+esc(row.handle)+'" title="효과 상세" aria-label="효과 상세 '+esc(row.handle)+'">…</button></th>'+'<td data-ability-field="effect|'+esc(row.handle)+'|level" title="'+esc(row.level??1)+'"><input type="number" data-effect-level="'+esc(row.handle)+'" value="'+esc(row.level??1)+'" min="0" max="1000000000" step="any" aria-label="효과 레벨 '+esc(row.handle)+'"></td>'+cell('effect|'+row.handle+'|stacks',row.stacks)+cell('effect|'+row.handle+'|remaining',row.remaining<0?'∞':row.remaining)+'</tr>').join('');
 return '<div class="ability-readout" data-ability-readout data-ability-structure="'+esc(signature(state))+'" data-ability-pages="'+esc(JSON.stringify(view))+'"><table><thead><tr><th>속성</th><th>기본</th><th>현재</th><th>최소</th><th>최대</th></tr></thead><tbody>'+attributes+'</tbody></table>'+navigation(Object.keys(state.attributes||{}).length,'attributes')+'<table><thead><tr><th>능력</th><th>상태</th><th>재사용(s)</th></tr></thead><tbody>'+abilities+'</tbody></table>'+navigation(Object.keys(state.abilities||{}).length,'abilities')+(effects?'<table><thead><tr><th>효과</th><th>레벨</th><th>중첩</th><th>남은(s)</th></tr></thead><tbody>'+effects+'</tbody></table>'+navigation((state.effects||[]).length,'effects'):'')+'</div>';
}
export function updateAbilityReadout(root,object){
 const element=root.querySelector('[data-ability-readout]'),state=object?.gameplayDebug?.ability;if(!element||!state)return;
 readoutOwners.set(root,object);if(root.addEventListener&&!readoutRoots.has(root)){readoutRoots.add(root);root.addEventListener('click',event=>{const button=event.target.closest('[data-ability-page]');if(!button||!root.contains(button))return;const element=button.closest('[data-ability-readout]'),view=JSON.parse(element.dataset.abilityPages||'{}');view[button.dataset.abilityPage]=(view[button.dataset.abilityPage]||0)+Number(button.dataset.abilityPageDelta);element.outerHTML=abilityReadout(readoutOwners.get(root)?.gameplayDebug?.ability||{},view);});}
 if(element.dataset.abilityStructure!==signature(state)){element.outerHTML=abilityReadout(state,JSON.parse(element.dataset.abilityPages||'{}'));return;}
 const effects=new Map(state.effects.map(e=>[e.handle,e]));for(const cell of element.querySelectorAll('[data-ability-field]')){const [section,key,field]=cell.dataset.abilityField.split('|'),row=section==='attribute'?state.attributes[key]:section==='ability'?state.abilities[key]:effects.get(key),value=row?.[field],text=field==='inhibited'?(value?'억제':'활성'):field==='active'?(value?'활성':'대기'):field==='remaining'&&value<0?'∞':typeof value==='number'?(['cooldown','remaining'].includes(field)?value.toFixed(2):number(value)):String(value??'—');const input=cell.querySelector?.('[data-effect-level]');if(input){if(input.ownerDocument.activeElement!==input&&input.value!==String(value??1))input.value=String(value??1);}else if(cell.textContent!==text)cell.textContent=text;const title=field==='inhibited'?text:String(value);if(cell.title!==title)cell.title=title;}
}
